/**
 * pi-handoff-gate
 *
 * 长任务自动续跑：agent 不因"本轮结束"或上下文将尽而停下等用户输入"继续"。
 * 阶段完成（milestone）不交还控制权、继续自动续跑；
 * 只有需要用户决策、无法继续、全部完成时（调用 report_to_user
 * 的 decision/blocked/done）才交还控制权。
 *
 * 机制（见 gate.ts / todo.ts 的纯函数判定）：
 * - before_agent_start：每次新用户输入重置计数，并追加系统提示 section；
 *   pi-agent-resilience 的自动恢复（sendUserMessage）触发时会再进入本事件，
 *   此时按 pi.events 的 auto-resume 信号跳过重置（同一逻辑 run）；
 * - tool_call：记录最后一次工具调用（"已汇报"状态以最后一次调用为准）；
 * - report_to_user execute：记录汇报类别（所有 kind 均不终止 run；
 *   decision/blocked/done 由工具结果要求模型再以一轮普通文本输出
 *   最终总结/答复后自然结束，保证最终回答存在）；kind=done 且 Todo 仍有
 *   未完成项时拒绝（同一 run 前两次拒绝、第 3 次放行）；
 * - agent_before_settle：report_to_user（decision/blocked/done，且此后无
 *   其他调用）→ 放行；milestone 或类别缺失（null）不放行（阶段完成
 *   继续续跑）；否则续跑并附催促消息；达到续跑上限或续跑后无工具调用
 *   则熔断，追加说明停止原因的可见消息（不续跑）。每次放行/熔断/续跑
 *   写一行原因日志到扩展目录 handoff-gate.log。边界已有 pi-agent-resilience
 *   条目、或最后一条 llmMessages 是空 assistant 时让出，避免双扩展相互覆盖/抑制。
 * - 等待确认：用户消息含"先回答/先评审/先分析/确认后再实施/等我判断"等意思时为
 *   decision 停止点（system section 注入）；自动续跑的催促消息明写"本消息不代表用户
 *   已授权"，用来抵消"催促被当成授权后自行推进"。
 * - Todo：todo 工具与 /todo 命令；状态存工具结果 details，在 session_start /
 *   session_tree 从 getBranch() 重建（随会话分支；压缩不影响）；todo 面板（setWidget
 *   belowEditor）显示当前环节标题（in_progress 优先；模型未标记时回退第一个 pending）。
 *
 * 配置（CLI flag，不传时用默认值）：
 * - --handoff-max-continue <n>        本次 run 最大自动续跑次数（默认 40）
 * - --handoff-no-progress-tolerance <n>  连续无工具调用续跑的容忍次数（默认 1）
 * - --handoff-todo-stale-calls <n>   自上次 todo 调用起累计多少其它工具调用后，在续跑催促
 *                                    里附“清单陈旧”提醒（默认 12；0 = 关闭）
 * - --handoff-disable                禁用 gate 自动行为（默认 false）：
 *                                    不注入系统提示、不做工具判定、不续跑；
 *                                    todo 工具//todo 与持久化仍保留，done 校验不生效
 */

import { appendFileSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { Type } from "@earendil-works/pi-ai";
import {
  copyToClipboard,
  defineTool,
  type ExtensionAPI,
  type ExtensionContext,
} from "@earendil-works/pi-coding-agent";
import { buildAllcopyText, formatAllcopyStats } from "./allcopy.ts";
import {
  DEFAULT_MAX_AUTO_CONTINUE,
  DEFAULT_NO_PROGRESS_TOLERANCE,
  REPORT_TOOL_NAME,
  RESILIENCE_AUTO_RESUME_CHANNEL,
  RESILIENCE_PRESENT_CHANNEL,
  appendEntries,
  decideDoneOpenTasks,
  decideMilestoneInProgress,
  decideSettle,
  hasResilienceEntry,
  initialGateState,
  isEmptyAssistantMessage,
  recordToolCall,
  type GateState,
  type HandoffGateConfig,
  type LogReason,
  type ReportKind,
} from "./gate.ts";
import {
  DEFAULT_TODO_STALE_CALLS,
  EMPTY_TODO_STATE,
  NUDGE_TODO_LIMIT,
  TODO_ENTRY_NAME,
  TODO_TOOL_NAME,
  formatTodoWidget,
  hasOpenItems,
  currentInProgress,
  reduce as reduceTodo,
  render as renderTodos,
  renderOpenItems,
  selectTodoState,
  staleTodoNote,
  todoAdvanceReminder,
  type TodoAction,
  type TodoState,
  type TodoWidgetRole,
} from "./todo.ts";

/** Todo 面板的 key（setWidget，placement=belowEditor） */
const TODO_WIDGET_KEY = "todo";

/** 面板各角色对应的主题色（accent/warning/dim/success 在 dark/light 两套主题均存在） */
const TODO_ROLE_COLOR: Record<TodoWidgetRole, "accent" | "warning" | "dim" | "success"> = {
  header: "accent",
  active: "accent",
  blocked: "warning",
  pending: "dim",
  alldone: "success",
};

const FLAG_MAX_CONTINUE = "handoff-max-continue";
const FLAG_NO_PROGRESS_TOLERANCE = "handoff-no-progress-tolerance";
const FLAG_TODO_STALE_CALLS = "handoff-todo-stale-calls";
const FLAG_DISABLE = "handoff-disable";

/** 系统提示 section 名，须匹配 /^[a-z][a-z0-9_-]*$/ 且非 "preamble" */
const SYSTEM_SECTION_NAME = "handoff-gate";

const SYSTEM_PROMPT_SECTION = `长任务自动续跑规则（${SYSTEM_SECTION_NAME}）：
- 不要因"本轮结束"或上下文不足而停下等待用户输入"继续"；Pi 会自动管理上下文（含自动压缩），继续工作即可。
- 普通进展不要汇报，直接继续调用工具推进任务。
- 阶段完成时：先在回复正文写出阶段汇报（summary），再调用 ${REPORT_TOOL_NAME}(kind=milestone)，然后直接继续下一阶段，不要等待用户、不要停在本轮结束。
- 只有需要用户决策（kind=decision）、无法继续（kind=blocked）、全部完成（kind=done）时才调用 ${REPORT_TOOL_NAME}；调用后会再获得一轮输出机会，用普通文本向用户给出最终总结/答复（不要再调用工具），然后本轮自然结束。
- summary 用一句话概括，保持 10 行以内，确保终端完整显示。
- 调用 ${REPORT_TOOL_NAME} 前，必须先在回复正文写出 summary 文本（一行），再调用工具；否则 /copy 复制不到汇报内容（工具调用不是 assistant 文本）。
- 用户消息含"先回答/先评审/先分析/确认后再实施/等我判断"等意思时，这是 decision 停止点：先在正文写出结论，再调用 ${REPORT_TOOL_NAME}(kind=decision) 并停下，不用 milestone，用户确认前不实施。
- 收到自动续跑催促不代表用户已确认；正在等待用户确认时，仍调用 ${REPORT_TOOL_NAME}(kind=decision)，不得开始实施。
- 多步任务（预计 3 步以上）先用 todo(action=set, items=[...]) 建步骤清单（set 会自动把第一项标为 in_progress）；每完成一步立即调用 todo(action="advance") 推进（当前项置 done、下一项置 in_progress，比 update 少一次调用），需要单独改状态/文本时用 update；不要攒到最后一次性批量更新；清单全部完成后才调用 ${REPORT_TOOL_NAME}(kind=done)。
- 阶段汇报（kind=milestone）前先同步清单：若清单里还有 in_progress 项，该次汇报会被拒并提示先标 done（同一 run 内第 3 次自动放行）。
- 无法完成的项用 todo(action=update, id=.., status=skipped) 标记跳过（skipped 与 done 一样不算未完成）；暂时受阻的项用 status=blocked 标记（会以 ⚠ 提示，仍算未完成）。
- 仍有未完成项时调用 done 会被拒绝并要求继续（同一轮内连续第 3 次才放行）。
- 单步/琐碎任务不要建清单。`;

const NUDGE_MESSAGE = `继续执行下一步，不要总结，不要询问是否继续；只有需要用户决策、无法继续或全部完成时才调用 ${REPORT_TOOL_NAME}。若上一条回复正在等待用户确认或评审，本消息不代表用户已授权：调用 ${REPORT_TOOL_NAME}(kind=decision) 并停下，不要实施。`;

function stopMessage(reason: "max_continue_fuse" | "no_progress_fuse", config: HandoffGateConfig): string {
  if (reason === "max_continue_fuse") {
    return `pi-handoff-gate：已达最大自动续跑次数（${config.maxAutoContinue}），停止自动续跑。请检查代理状态，必要时直接输入新的指令。`;
  }
  return "pi-handoff-gate：续跑后无任何工具调用（无进展），停止自动续跑。请检查代理状态，必要时直接输入新的指令。";
}

/**
 * 读取数值 flag 并强制转换。CLI 传入的值是字符串，未传时是注册的默认值（number）；
 * 非法值回退默认值。
 */
function readFlag(pi: ExtensionAPI, name: string, fallback: number): number {
  const value = pi.getFlag(name);
  if (typeof value === "number" && Number.isSafeInteger(value) && value >= 0) {
    return value;
  }
  if (typeof value === "string") {
    const parsed = Number(value);
    if (Number.isSafeInteger(parsed) && parsed >= 0) {
      return parsed;
    }
  }
  return fallback;
}

/** --handoff-disable 为 true 时扩展完全不介入：不注入提示、不做工具判定、不续跑。 */
function isDisabled(pi: ExtensionAPI): boolean {
  return pi.getFlag(FLAG_DISABLE) === true;
}

export default function (pi: ExtensionAPI) {
  pi.registerFlag(FLAG_MAX_CONTINUE, {
    description: "pi-handoff-gate: max automatic continuations per run (default 40)",
    type: "number",
    default: DEFAULT_MAX_AUTO_CONTINUE,
  });
  pi.registerFlag(FLAG_NO_PROGRESS_TOLERANCE, {
    description: "pi-handoff-gate: consecutive auto-continuations without tool calls before stopping (default 1)",
    type: "number",
    default: DEFAULT_NO_PROGRESS_TOLERANCE,
  });
  pi.registerFlag(FLAG_DISABLE, {
    description: "pi-handoff-gate: disable all gating (no prompt injection, no tool tracking, no continuation; default false)",
    type: "boolean",
    default: false,
  });
  pi.registerFlag(FLAG_TODO_STALE_CALLS, {
    description:
      "pi-handoff-gate: tool calls since the last todo update before a stale-list reminder is attached to the nudge (default 12; 0 disables)",
    type: "number",
    default: DEFAULT_TODO_STALE_CALLS,
  });

  // /allcopy：只读会话，按结构标记逐轮汇总并复制到剪贴板。
  // 不参与 gate 判定，也不改任何会话状态；不受 --handoff-disable 影响（用户显式触发）。
  pi.registerCommand("allcopy", {
    description:
      "复制最近一个任务范围（逐轮）内 assistant 的回答到剪贴板",
    handler: async (_args, ctx) => {
      let result;
      try {
        result = buildAllcopyText(ctx.sessionManager.getBranch());
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        ctx.ui.notify(`/allcopy 读取会话失败：${message}`, "error");
        return;
      }
      if (result.text.length === 0) {
        ctx.ui.notify("未找到符合条件的内容（未写入剪贴板，剪贴板保持原内容）", "warning");
        return;
      }
      // 加固：复制失败重试 1 次（X11 下偶发写不进时，重试即成功；见 CHANGELOG 第二十轮）。
      let copyError = "";
      for (let attempt = 1; attempt <= 2; attempt += 1) {
        try {
          await copyToClipboard(result.text);
          ctx.ui.notify(formatAllcopyStats(result), "info");
          return;
        } catch (error) {
          copyError = error instanceof Error ? error.message : String(error);
        }
      }
      // 兜底：复制失败时落盘到临时文件，保证汇总内容不丢。
      let savedPath: string | null = null;
      try {
        const dir = mkdtempSync(join(tmpdir(), "pi-allcopy-"));
        savedPath = join(dir, "allcopy.md");
        writeFileSync(savedPath, result.text, "utf8");
      } catch {
        savedPath = null;
      }
      ctx.ui.notify(
        `/allcopy 复制到剪贴板失败：${copyError}${savedPath ? `；已保存到 ${savedPath}` : ""}`,
        "error",
      );
    },
  });

  // 状态只保存在扩展闭包内；判定逻辑全部在 gate.ts 纯函数中。
  let state: GateState = initialGateState();
  // 与 pi-agent-resilience 的协作信号（pi.events 共享总线，不用全局变量）：
  // - resiliencePresent：resilience 已加载（session_start 广播），
  //   gate 先于它处理同一空响应边界时让出，避免注入 entries 抑制其恢复；
  // - expectResilienceResume：resilience 即将 sendUserMessage 自动恢复，
  //   该次 before_agent_start 不重置计数（否则 autoContinues 被清零）。
  let resiliencePresent = false;
  let expectResilienceResume = false;
  pi.events.on(RESILIENCE_PRESENT_CHANNEL, () => {
    resiliencePresent = true;
  });
  pi.events.on(RESILIENCE_AUTO_RESUME_CHANNEL, () => {
    expectResilienceResume = true;
  });

  // ---- Todo：状态由闭包持有；用工具结果 details 持久化，随会话分支重建 ----
  let todoState: TodoState = EMPTY_TODO_STATE;
  // 同一 run 内 done 因“有未完成项”被拒的次数（用于第 3 次放行）
  let doneOpenTaskAttempts = 0;
  // 同一 run 内自上次 todo 调用以来的其它工具调用数（用于续跑催促里的清单陈旧提醒）
  let toolCallsSinceTodoUpdate = 0;
  // 同一 run 内 milestone 因“仍有 in_progress 项”被拒的次数（用于第 3 次放行）
  let milestoneInProgressAttempts = 0;
  // 同一 run 内「清单未同步」中途提醒：已发次数 + 上次提醒时的调用计数
  let todoRemindersSent = 0;
  let todoReminderAtCalls = 0;
  // 面板上次渲染出的文本（节流：内容不变时不重绘）
  let lastWidgetText = "";

  /** 从当前分支的 todo 工具结果重建清单（会话启动 / 树切换时；只认本工具名） */
  const reconstructTodo = (ctx: ExtensionContext): void => {
    try {
      todoState = selectTodoState(ctx.sessionManager.getBranch());
    } catch {
      // 重建失败不影响新会话：从空清单开始
      todoState = EMPTY_TODO_STATE;
    }
    toolCallsSinceTodoUpdate = 0;
  };

  /**
   * 刷新 Todo 多行面板（setWidget key="todo", placement=belowEditor）：
   * - 无 UI（print/JSON 等）或 --handoff-disable 时不设置；
   * - 清单为空返回 [] → setWidget(key, undefined) 清除面板；
   * - 按 formatTodoWidget 的 role 用主题 API 上色（header/active=accent、blocked=warning、pending/more=dim、alldone=success）；
   * - 任何失败不影响扩展（try/catch）。
   */
  const updateTodoView = (ctx: ExtensionContext | undefined): void => {
    if (isDisabled(pi)) return;
    if (!ctx?.hasUI) return;
    try {
      const lines = formatTodoWidget(todoState, {
        staleCalls: toolCallsSinceTodoUpdate,
        staleThreshold: readTodoStaleCalls(),
      });
      if (lines.length === 0) {
        if (lastWidgetText !== "") {
          lastWidgetText = "";
          ctx.ui.setWidget(TODO_WIDGET_KEY, undefined);
        }
        return;
      }
      const theme = ctx.ui.theme;
      const colored = lines.map((line) => theme.fg(TODO_ROLE_COLOR[line.role], line.text));
      const text = colored.join("\n");
      // 节流：非 todo 事件也会刷新面板，内容未变时不做无谓重绘
      if (text === lastWidgetText) return;
      lastWidgetText = text;
      ctx.ui.setWidget(TODO_WIDGET_KEY, colored, { placement: "belowEditor" });
    } catch {
      /* 面板是 best-effort：失败不破坏扩展 */
    }
  };

  pi.on("session_start", (_event, ctx) => {
    reconstructTodo(ctx);
    updateTodoView(ctx);
  });
  pi.on("session_tree", (_event, ctx) => {
    reconstructTodo(ctx);
    updateTodoView(ctx);
  });

  pi.registerTool(
    defineTool({
      name: TODO_TOOL_NAME,
      label: "Todo",
      description:
        "维护多步任务清单。action: set=设置/替换清单(items), update=更新一项(id[, status[, text]]), advance=推进一项（当前 in_progress 置 done、下一个 pending 置 in_progress）, list=查看, clear=清空。status: pending|in_progress|done|skipped|blocked（done/skipped 为终态；blocked 表示受阻、未完成）。set 会自动把第一项标为 in_progress。每完成一步推荐调用一次 advance（比 update 少一次调用）；需要单独改状态/文本时用 update。仅当任务预计 3 步以上时使用。",
      parameters: Type.Object({
        action: Type.Union(
          [
            Type.Literal("set"),
            Type.Literal("update"),
            Type.Literal("advance"),
            Type.Literal("list"),
            Type.Literal("clear"),
          ],
          { description: "操作" },
        ),
        items: Type.Optional(Type.Array(Type.String(), { description: "set 的清单文本" })),
        id: Type.Optional(Type.Number({ description: "update 的目标 id" })),
        status: Type.Optional(
          Type.Union(
            [
              Type.Literal("pending"),
              Type.Literal("in_progress"),
              Type.Literal("done"),
              Type.Literal("skipped"),
              Type.Literal("blocked"),
            ],
            { description: "update 的新状态" },
          ),
        ),
        text: Type.Optional(Type.String({ description: "update 的新文本（可选）" })),
      }),
      async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
        const persist = (action: string, next: TodoState) => ({
          content: [{ type: "text" as const, text: renderTodos(next) }],
          details: { action, state: next },
        });
        let action: TodoAction;
        switch (params.action) {
          case "set":
            action = { type: "set", items: params.items ?? [] };
            break;
          case "update":
            action = {
              type: "update",
              id: params.id ?? -1,
              status: params.status,
              text: params.text,
            };
            break;
          case "advance":
            action = { type: "advance" };
            break;
          case "clear":
            action = { type: "clear" };
            break;
          default:
            updateTodoView(_ctx);
            return persist("list", todoState);
        }
        const result = reduceTodo(todoState, action);
        if (!result.ok) {
          // 非法动作不改状态，只把错误回给模型
          updateTodoView(_ctx);
          return {
            content: [{ type: "text", text: `错误：${result.error}\n${renderTodos(result.state)}` }],
            details: { action: params.action, state: result.state },
          };
        }
        todoState = result.state;
        toolCallsSinceTodoUpdate = 0; // 本次 todo 调用已同步清单，陈旧计数归零
        todoReminderAtCalls = 0; // 中途提醒的间隔从本次同步重新起算（次数预算仍按 run 计）
        const prefix =
          params.action === "update" && params.id !== undefined
            ? `已更新 #${params.id}\n`
            : params.action === "advance"
              ? "已推进一项\n"
              : "";
        updateTodoView(_ctx);
        return {
          content: [{ type: "text", text: `${prefix}${renderTodos(todoState)}` }],
          details: { action: params.action, state: todoState },
        };
      },
    }),
  );

  pi.registerCommand("todo", {
    description: "查看当前任务清单；/todo clear 清空",
    handler: async (args, ctx) => {
      if ((args ?? "").trim() === "clear") {
        todoState = reduceTodo(todoState, { type: "clear" }).state;
        // 命令不产生工具结果，用 custom entry 持久化，重启/切分支后不复活旧清单
        try {
          pi.appendEntry(TODO_ENTRY_NAME, { state: todoState });
        } catch {
          /* appendEntry 失败不影响当前会话内状态 */
        }
        updateTodoView(ctx);
        ctx.ui.notify("已清空任务清单", "info");
        return;
      }
      ctx.ui.notify(renderTodos(todoState), "info");
    },
  });

  const readConfig = (): HandoffGateConfig => ({
    maxAutoContinue: readFlag(pi, FLAG_MAX_CONTINUE, DEFAULT_MAX_AUTO_CONTINUE),
    noProgressTolerance: readFlag(pi, FLAG_NO_PROGRESS_TOLERANCE, DEFAULT_NO_PROGRESS_TOLERANCE),
  });

  /** 清单陈旧提醒阈值（独立 flag；不进 HandoffGateConfig，避免改动 gate.ts 的 settle 判定契约） */
  const readTodoStaleCalls = (): number =>
    readFlag(pi, FLAG_TODO_STALE_CALLS, DEFAULT_TODO_STALE_CALLS);

  /** settle/续跑原因日志：扩展目录相对路径 handoff-gate.log，写入失败不破坏扩展 */
  const LOG_URL = new URL("./handoff-gate.log", import.meta.url);
  const logSettle = (
    reason: LogReason,
    autoContinues: number,
    modelId?: string,
  ): void => {
    try {
      const model = modelId ? ` model=${modelId}` : "";
      appendFileSync(
        LOG_URL,
        `${new Date().toISOString()} ${reason} autoContinues=${autoContinues}${model}\n`,
      );
    } catch {
      // 日志写入失败（如只读文件系统）不破坏扩展行为
    }
  };

  /** 从 agent_before_settle 事件取当前模型 id（context 中最后一个 model_change 条目）；取不到返回 undefined */
  const currentModelId = (event: unknown): string | undefined => {
    try {
      const entries = (event as { context?: { contextEntries?: unknown[] } })?.context
        ?.contextEntries;
      if (!Array.isArray(entries)) return undefined;
      let modelId: string | undefined;
      for (const entry of entries) {
        const source = (entry as { sourceEntry?: { type?: unknown; modelId?: unknown } })
          ?.sourceEntry;
        if (source?.type === "model_change" && typeof source.modelId === "string") {
          modelId = source.modelId;
        }
      }
      return modelId;
    } catch {
      return undefined;
    }
  };

  pi.registerTool(
    defineTool({
      name: REPORT_TOOL_NAME,
      label: "Report to user",
      description:
        "向用户汇报。kind: milestone=阶段完成（汇报后直接继续下一阶段，不结束本轮）, decision=需要用户决策, blocked=无法继续, done=全部完成。summary 为一句话汇报（10 行以内）。调用前须先在回复正文写出 summary 文本。decision/blocked/done 调用后，还须以普通文本向用户输出最终总结/答复，然后结束本轮，不要再调用其他工具。",
      parameters: Type.Object({
        kind: Type.Union(
          [
            Type.Literal("milestone"),
            Type.Literal("decision"),
            Type.Literal("blocked"),
            Type.Literal("done"),
          ],
          { description: "汇报类别" },
        ),
        summary: Type.String({ description: "一句话汇报内容（10 行以内）" }),
      }),
      async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
        // 记录汇报类别供 settle 判定（所有 kind 均不终止 run）
        state = { ...state, lastReportKind: params.kind };
        // Todo 联动：done 且有未完成项 → 拒绝并要求继续（同一 run 内第 3 次放行）；
        // milestone/decision/blocked 不受影响。--handoff-disable 时联动全部不生效。
        if (!isDisabled(pi)) {
          // 规则 A：milestone 汇报前先同步清单（清单里仍有 in_progress 项 → 拒绝，第 3 次放行）
          const milestoneVerdict = decideMilestoneInProgress(
            params.kind,
            currentInProgress(todoState) !== undefined,
            milestoneInProgressAttempts + 1,
          );
          if (milestoneVerdict === "reject") {
            milestoneInProgressAttempts += 1;
            logSettle("milestone_rejected_in_progress", state.autoContinues);
            state = { ...state, lastReportKind: null };
            const cur = currentInProgress(todoState);
            return {
              content: [
                {
                  type: "text",
                  text: `[milestone 被拒] 阶段汇报前请先同步清单：#${cur?.id} ${cur?.text} 仍是 in_progress。先用 todo(action="update", id=${cur?.id}, status="done") 把它标完成（本 run 内第 3 次会自动放行）；若要同时开始下一项，用 todo(action="advance") 后再汇报仍会被拒，建议汇报后再 advance。\n${renderTodos(todoState)}`,
                },
              ],
              details: { kind: params.kind, summary: params.summary, rejected: "in_progress" },
            };
          }
          if (milestoneVerdict === "override") {
            milestoneInProgressAttempts += 1;
            logSettle("milestone_override_in_progress", state.autoContinues);
          }
          const verdict = decideDoneOpenTasks(
            params.kind,
            hasOpenItems(todoState),
            doneOpenTaskAttempts + 1,
          );
          if (verdict === "reject") {
            doneOpenTaskAttempts += 1;
            logSettle("done_rejected_open_tasks", state.autoContinues);
            // lastReportKind 置空：settle 不会放行，由催促逻辑续跑
            state = { ...state, lastReportKind: null };
            return {
              content: [
                {
                  type: "text",
                  text: `[done 被拒] 仍有未完成任务，请继续完成后更新清单：\n${renderTodos(todoState)}\n完成后再调用 ${REPORT_TOOL_NAME}(kind=done)。`,
                },
              ],
              details: { kind: params.kind, summary: params.summary, rejected: "open_tasks" },
            };
          }
          if (verdict === "override") {
            doneOpenTaskAttempts += 1;
            logSettle("done_override_open_tasks", state.autoContinues);
            // 放行：lastReportKind 保持 done
          }
        }
        // decision/blocked/done：不 terminate，模型获得 follow-up 轮，
        // 由工具结果中的指令要求其以普通文本输出最终答复后结束，
        // 保证 run 结束时存在 assistant 文本（/copy 与 print 模式可用）
        const text =
          params.kind === "milestone"
            ? `[milestone] ${params.summary}`
            : `[${params.kind}] ${params.summary}\n请现在以普通文本向用户输出最终总结/答复后结束本轮，不要再调用工具。`;
        return {
          content: [{ type: "text", text }],
          details: { kind: params.kind, summary: params.summary },
        };
      },
    }),
  );

  pi.on("before_agent_start", (event) => {
    if (isDisabled(pi)) {
      return;
    }
    const systemSection = (): void => {
      event.systemPromptOptions.sections[SYSTEM_SECTION_NAME] = SYSTEM_PROMPT_SECTION;
    };
    // resilience 用 sendUserMessage 自动恢复：这是一次新的 before_agent_start，
    // 但属于同一逻辑 run，不能清掉 gate 的续跑预算（否则 maxContinue 永达不到）。
    if (expectResilienceResume) {
      expectResilienceResume = false;
      systemSection();
      return;
    }
    // 每次新用户输入：重置计数，并追加系统提示 section（对整个 run 含续跑生效）
    state = initialGateState();
    doneOpenTaskAttempts = 0;
    milestoneInProgressAttempts = 0;
    toolCallsSinceTodoUpdate = 0;
    todoRemindersSent = 0;
    todoReminderAtCalls = 0;
    systemSection();
  });

  pi.on("tool_call", (event, ctx) => {
    if (isDisabled(pi)) {
      return;
    }
    state = recordToolCall(state, event.toolName);
    // todo 自身的调用在 execute 里归零；这里只累计其它工具调用，供陈旧提醒/面板标注判断
    if (event.toolName !== TODO_TOOL_NAME) {
      toolCallsSinceTodoUpdate += 1;
      // 陈旧标注随计数变化：让面板表头跟上（updateTodoView 内含“内容不变不重绘”节流）
      if (todoState.items.length > 0) updateTodoView(ctx);
    }
  });

  // 中途提醒：长轮次里模型连续调用工具、从不 settle，agent_before_settle 上的陈旧提醒
  // 永远不会触发（正是 2026-10-11 观察到的问题）。turn_end 是每次「一条 assistant 消息 +
  // 其工具结果」结束时的边界，可在此注入一条隐藏提醒并 continue，让当前 run 内就同步清单。
  pi.on("turn_end", (event, ctx) => {
    if (isDisabled(pi)) {
      return {};
    }
    // 终态交接（decision/blocked/done）已把控制权交还用户：不续跑，不抢在用户之前继续工作
    if (
      state.lastReportKind === "decision" ||
      state.lastReportKind === "blocked" ||
      state.lastReportKind === "done"
    ) {
      return {};
    }
    // 同一边界上 resilience 已在 entries 里放了提案：本扩展让出，避免互相覆盖
    if (hasResilienceEntry(event.entries)) {
      return {};
    }
    const note = todoAdvanceReminder(
      todoState,
      toolCallsSinceTodoUpdate,
      readTodoStaleCalls(),
      todoRemindersSent,
      todoReminderAtCalls,
    );
    if (!note) {
      return {};
    }
    todoRemindersSent += 1;
    todoReminderAtCalls = toolCallsSinceTodoUpdate;
    try {
      logSettle("todo_stale_reminder", state.autoContinues);
    } catch {
      /* 日志失败不影响扩展 */
    }
    updateTodoView(ctx);
    return {
      entries: appendEntries(event.entries, {
        type: "custom_message",
        customType: SYSTEM_SECTION_NAME,
        content: note,
        display: false,
      }),
      continue: true,
    };
  });

  pi.on("agent_before_settle", (event) => {
    if (isDisabled(pi)) {
      return {};
    }
    // 同一边界上其他扩展（pi-agent-resilience）已接管续跑：本次让出，
    // 不判定、不消耗自己的续跑预算、不覆盖其 entries。
    if (hasResilienceEntry(event.entries)) {
      return {};
    }
    // gate 先于 resilience 处理同一空响应边界时，注入 entries 会让 resilience
    // 看不到“最后一条是空 assistant”而跳过恢复；resilience 在场时 gate 一律让出。
    if (resiliencePresent) {
      const llm = event.context?.llmMessages;
      const last = Array.isArray(llm) ? llm[llm.length - 1] : undefined;
      if (isEmptyAssistantMessage(last)) {
        return {};
      }
    }
    const config = readConfig();
    const { decision, state: nextState } = decideSettle(state, config, event.outcome);
    const autoContinues =
      decision.action === "continue" ? nextState.autoContinues : state.autoContinues;
    const modelId = currentModelId(event);

    if (decision.action === "release" || decision.action === "stop") {
      // 放行/熔断均记录一行原因日志
      logSettle(decision.reason, autoContinues, modelId);
    }

    if (decision.action === "release") {
      // 最后一次工具调用是 report_to_user（decision/blocked/done）：放行 settle
      return {};
    }

    if (decision.action === "stop") {
      // abort/error：run 已中断/出错，原因对用户已可见，只写日志不追加消息
      if (decision.reason === "abort" || decision.reason === "error") {
        return {};
      }
      // 熔断：追加可见停止原因，不续跑（reason 收窄为两种熔断原因）
      if (
        decision.reason === "no_progress_fuse" ||
        decision.reason === "max_continue_fuse"
      ) {
        return {
          entries: appendEntries(event.entries, {
            type: "custom_message",
            customType: SYSTEM_SECTION_NAME,
            content: stopMessage(decision.reason, config),
          }),
        };
      }
      return {};
    }

    // 续跑：记录 nudge 日志，附催促消息（custom_message 使续跑具备可运行的模型上下文）
    state = nextState;
    logSettle("nudge", nextState.autoContinues, modelId);
    // 有未完成项时在 nudge 内附带剩余清单（上限 NUDGE_TODO_LIMIT 项），便于模型直接接着做；
    // 长时间未更新清单时再附一行陈旧提醒（阈值 --handoff-todo-stale-calls，0=关闭）；
    // --handoff-disable 时本处理器已提前返回，两者都不会附带。
    const remaining = renderOpenItems(todoState);
    const staleNote = staleTodoNote(todoState, toolCallsSinceTodoUpdate, readTodoStaleCalls());
    const sections = [NUDGE_MESSAGE];
    if (staleNote) sections.push(staleNote);
    if (remaining) {
      sections.push(
        `当前未完成清单（最多列出 ${NUDGE_TODO_LIMIT} 项；请先同步清单：已完成项改 done、正在做的项改 in_progress）：\n${remaining}`,
      );
    }
    const nudgeContent = sections.join("\n\n");
    return {
      entries: appendEntries(event.entries, {
        type: "custom_message",
        customType: SYSTEM_SECTION_NAME,
        content: nudgeContent,
      }),
      continue: true,
    };
  });
}

extensions.pi-handoff-gate/gate.ts:
/**
 * pi-handoff-gate 纯函数判定模块。
 *
 * 不依赖 Pi 运行时，可直接用 node --test 单测。
 * 状态由扩展闭包持有，本模块只负责纯判定与状态迁移。
 */

export const REPORT_TOOL_NAME = "report_to_user";

/** report_to_user 的汇报类别 */
export type ReportKind = "milestone" | "decision" | "blocked" | "done";

/**
 * 边界事件（agent_before_settle）已有提案条目。Pi 的 emitBoundary 为替换语义：
 * 任一 handler 返回的 entries 会整体替换已有值，因此提案必须基于 event.entries 追加。
 * 本模块只透传，不解析条目内容。
 */
export interface BoundaryEntry {
  type: string;
  customType?: string;
  content?: string;
  display?: boolean;
}

/** pi-agent-resilience 注入条目的 customType，用于识别同一边界上其他扩展已接管 */
export const RESILIENCE_CUSTOM_TYPE = "pi-agent-resilience";

/** pi-agent-resilience 在 session_start 广播“已加载”的通道（shared pi.events） */
export const RESILIENCE_PRESENT_CHANNEL = "pi-agent-resilience:present";

/** pi-agent-resilience 在 sendUserMessage 自动恢复前广播的通道 */
export const RESILIENCE_AUTO_RESUME_CHANNEL = "pi-agent-resilience:auto-resume";

/**
 * 一条消息（边界 context.llmMessages 的元素）是否为空最终 assistant 回复：
 * role=assistant 且既无有效 text 块也无 toolCall。此类回复（空响应 / thinking-only）
 * 由 pi-agent-resilience 负责恢复；gate 若先于它处理同一边界并注入 entries，
 * 会把 boundary context 的最后一条 llmMessage 变成注入的 user 消息，导致 resilience
 * 的 `isLastAssistant` 判定失败、恢复被静默抑制。gate 据此让出（仍需 resilience 在场）。
 */
export function isEmptyAssistantMessage(message: unknown): boolean {
  if (message === null || typeof message !== "object") return false;
  const m = message as { role?: unknown; content?: unknown };
  if (m.role !== "assistant") return false;
  const content = Array.isArray(m.content) ? m.content : [];
  const hasText = content.some((block) => {
    const b = block as { type?: unknown; text?: unknown } | null;
    return b?.type === "text" && typeof b.text === "string" && b.text.trim().length > 0;
  });
  const hasToolCall = content.some(
    (block) => (block as { type?: unknown } | null)?.type === "toolCall",
  );
  return !hasText && !hasToolCall;
}

/** 已有提案条目中是否含 pi-agent-resilience 的条目；是则 gate 本次让出 */
export function hasResilienceEntry(entries: BoundaryEntry[] | undefined): boolean {
  return (entries ?? []).some((e) => e.customType === RESILIENCE_CUSTOM_TYPE);
}

/** 按 resilience 的 priorEntries 写法追加我方条目，避免整体替换覆盖其他扩展的提案 */
export function appendEntries(
  prior: BoundaryEntry[] | undefined,
  ours: BoundaryEntry,
): BoundaryEntry[] {
  return [...(prior ?? []), ours];
}

export const DEFAULT_MAX_AUTO_CONTINUE = 40;
export const DEFAULT_NO_PROGRESS_TOLERANCE = 1;

export interface HandoffGateConfig {
  /** 本次 run 内最大自动续跑次数，达到后熔断 */
  maxAutoContinue: number;
  /** 连续零工具调用续跑的容忍次数，超过后熔断 */
  noProgressTolerance: number;
}

export interface GateState {
  /** 本次 run 内最后一次工具调用名；null 表示尚无工具调用 */
  lastToolName: string | null;
  /** 最后一次 report_to_user 的类别；由工具 execute 记录，非 report_to_user 调用清除 */
  lastReportKind: ReportKind | null;
  /** 上次续跑（或 run 开始）以来的工具调用次数 */
  toolCallsSinceContinue: number;
  /** 本次 run 内已执行的自动续跑次数 */
  autoContinues: number;
  /** 连续零工具调用的续跑次数 */
  noProgressStreak: number;
}

export function initialGateState(): GateState {
  return {
    lastToolName: null,
    lastReportKind: null,
    toolCallsSinceContinue: 0,
    autoContinues: 0,
    noProgressStreak: 0,
  };
}

/**
 * 记录一次工具调用。任何工具调用都会覆盖 lastToolName，
 * 因此"已汇报"状态（最后一次调用为 report_to_user）会被随后的其他调用失效。
 * lastReportKind 仅由 report_to_user 的 execute 记录（见 index.ts）；
 * 非 report_to_user 调用将其清除。
 */
export function recordToolCall(state: GateState, toolName: string): GateState {
  return {
    ...state,
    lastToolName: toolName,
    lastReportKind:
      toolName === REPORT_TOOL_NAME ? state.lastReportKind : null,
    toolCallsSinceContinue: state.toolCallsSinceContinue + 1,
  };
}

/** settle 放行/熔断原因，每次 settle 写入一行日志 */
export type SettleReason =
  | "report_done"
  | "report_decision"
  | "report_blocked"
  | "pure_chat"
  | "no_progress_fuse"
  | "max_continue_fuse"
  | "abort"
  | "error";

/** 日志原因：settle 原因 + 续跑催促 + Todo 联动（非 settle 边界写入） */
export type LogReason =
  | SettleReason
  | "nudge"
  | "todo_stale_reminder"
  | "done_rejected_open_tasks"
  | "done_override_open_tasks"
  | "milestone_rejected_in_progress"
  | "milestone_override_in_progress";

/** 有未完成 Todo 时，第几次 done 才强行放行（前两次拒绝并要求继续） */
export const DONE_OPEN_TASKS_OVERRIDE_AFTER = 3;

export type DoneOpenTaskVerdict = "release" | "reject" | "override";

/**
 * report_to_user(kind) 与 Todo 未完成项的联动判定。
 * - 非 done（business milestone/decision/blocked）：与改动前一致，直接 release；
 * - 无清单或清单全部完成：直接 release（无清单=行为完全不变）；
 * - done 且有未完成项：前两次 reject，第 DONE_OPEN_TASKS_OVERRIDE_AFTER 次 override
 *   （防止模型卡死时永远无法结束）。attempt 为本次 run 内 done+未完成的次数（1 起）。
 */
export function decideDoneOpenTasks(
  kind: ReportKind,
  hasOpenItems: boolean,
  attempt: number,
): DoneOpenTaskVerdict {
  if (kind !== "done") return "release";
  if (!hasOpenItems) return "release";
  return attempt >= DONE_OPEN_TASKS_OVERRIDE_AFTER ? "override" : "reject";
}

/** milestone 时清单里仍有 in_progress 项：第几次才强行放行 */
export const MILESTONE_IN_PROGRESS_OVERRIDE_AFTER = 3;

export type MilestoneVerdict = "release" | "reject" | "override";

/**
 * report_to_user(kind=milestone) 与 Todo 进行中项的联动（阶段边界同步）。
 * - 非 milestone，或清单无 in_progress 项：直接 release（无清单 = 行为不变）；
 * - 有 in_progress 项：前两次 reject（要求先用 update/advance 把它标 done），
 *   第 MILESTONE_IN_PROGRESS_OVERRIDE_AFTER 次 override（防卡死）。
 * attempt 为本次 run 内「milestone + 有 in_progress」的累计次数（1 起）。
 */
export function decideMilestoneInProgress(
  kind: ReportKind,
  hasInProgress: boolean,
  attempt: number,
): MilestoneVerdict {
  if (kind !== "milestone") return "release";
  if (!hasInProgress) return "release";
  return attempt >= MILESTONE_IN_PROGRESS_OVERRIDE_AFTER ? "override" : "reject";
}

export type SettleDecision =
  | { action: "release" | "stop"; reason: SettleReason }
  | { action: "continue" };

export interface SettleResult {
  decision: SettleDecision;
  /** 仅当 decision.action === "continue" 时为推进后的状态；否则为原状态 */
  state: GateState;
}

/**
 * agent_before_settle 判定。
 *
 * 规则（按优先级）：
 * 1. outcome 为 aborted/error → 停止（不续跑，错误/中断对用户已可见）
 * 2. 最后一次工具调用是 report_to_user 且类别非 milestone → 放行 settle
 *    （milestone 是阶段完成汇报，不终止 run：模型应直接继续下一阶段）
 * 3. 整个 run 无任何工具调用（lastToolName 为 null）→ 放行（对话型交互，
 *    不催促也不熔断）
 * 4. 上次续跑以来无任何工具调用且超过容忍度 → 熔断 no_progress_fuse
 * 5. 自动续跑次数已达上限 → 熔断 max_continue_fuse
 * 6. 否则 → 续跑（由调用方附催促消息并 continue: true）
 */
export function decideSettle(
  state: GateState,
  config: HandoffGateConfig,
  outcome: "completed" | "aborted" | "error",
): SettleResult {
  if (outcome === "aborted") {
    return { decision: { action: "stop", reason: "abort" }, state };
  }
  if (outcome === "error") {
    return { decision: { action: "stop", reason: "error" }, state };
  }
  if (state.lastToolName === REPORT_TOOL_NAME) {
    // 仅 decision/blocked/done 放行（交还控制权）。
    // milestone：阶段完成汇报，不放行——阶段完成不是终止点，
    // 继续走续跑逻辑（milestone 本身计为有进展的工具调用）。
    // lastReportKind 为 null（调用失败或参数非法）：同样不放行，
    // 按普通续跑逻辑处理。
    if (
      state.lastReportKind === "decision" ||
      state.lastReportKind === "blocked" ||
      state.lastReportKind === "done"
    ) {
      const reason: SettleReason =
        state.lastReportKind === "decision"
          ? "report_decision"
          : state.lastReportKind === "blocked"
            ? "report_blocked"
            : "report_done";
      return { decision: { action: "release", reason }, state };
    }
  }
  // 整个 run 无任何工具调用：对话型交互，非长任务，直接放行（不催促、不熔断）
  if (state.lastToolName === null) {
    return { decision: { action: "release", reason: "pure_chat" }, state };
  }
  const progress = state.toolCallsSinceContinue > 0;
  const noProgressStreak = progress ? 0 : state.noProgressStreak + 1;
  if (noProgressStreak > config.noProgressTolerance) {
    return { decision: { action: "stop", reason: "no_progress_fuse" }, state };
  }
  if (state.autoContinues >= config.maxAutoContinue) {
    return {
      decision: { action: "stop", reason: "max_continue_fuse" },
      state,
    };
  }
  return {
    decision: { action: "continue" },
    state: {
      ...state,
      autoContinues: state.autoContinues + 1,
      toolCallsSinceContinue: 0,
      noProgressStreak,
    },
  };
}
